```python
def query_db(query, args=(), one=False, commit=False):
    import sqlite3
    with sqlite3.connect(DB_FILENAME) as conn:
        conn.set_trace_callback(print)
        cur = conn.cursor()
        if args:
            cur.execute(query, args)
        else:
            cur.execute(query)
        if commit:
            conn.commit()
        return cur.fetchone() if one else cur.fetchall()
```

